
public class A1Q5 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		double r=7;
		double vol=2.0/3.0 * Math.PI * Math.pow(r, 3);
		double area=3 * Math.PI * Math.pow(r, 2);
		System.out.print("Radius = "+r+
				"\nVolume of hemisphere = "+vol+
				"\nTotal Surface Area of Hemisphere = "+area);
	}

}
